    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer and plr.Character then
            local head = plr.Character:FindFirstChild((_S[81])) or plr.Character:FindFirstChild((_S[80]))
            if head then
                local screenPos, onScreen = cam:WorldToViewportPoint(head.Position)
                if onScreen then
                    local dist = (Vector2.new(screenPos.X, screenPos.Y) - center).Magnitude
                    if dist < closestDist then
                        closestDist = dist
                        closest = plr
                    end
                end
            end
        end
    end
    return closest
end

local function StartAimbot()
    aimbotActive = true
    aimbotTarget = GetClosestToCenter()

    if aimbotConn then aimbotConn:Disconnect() end

    aimbotConn = RunService.RenderStepped:Connect(function()
        if not aimbotActive then return end

        if not aimbotTarget or not aimbotTarget.Character or not aimbotTarget.Character:FindFirstChild((_S[81])) then
            aimbotTarget = GetClosestToCenter()
            if not aimbotTarget then return end
        end

        local head = aimbotTarget.Character:FindFirstChild((_S[81])) or aimbotTarget.Character:FindFirstChild((_S[80]))
        if not head then return end

        local cam = Workspace.CurrentCamera
        local myPos = cam.CFrame.Position
        local targetPos = head.Position
        local dir = (targetPos - myPos).Unit

        cam.CFrame = CFrame.new(myPos, myPos + dir)
    end)
end

local function StopAimbot()
    aimbotActive = false
    aimbotTarget = nil
    if aimbotConn then
        aimbotConn:Disconnect()
        aimbotConn = nil
    end
end

local aimbotToggle = false
mm2Page:AddToggle((_S[82]), false, true, function(state)
    aimbotToggle = state
    if state then
        StartAimbot()
    else
        StopAimbot()
    end
end)

