    gmt.__namecall = newcclosure(function(self, ...)
        local method = getnamecallmethod()
        local args = {...}
        if silentAimEnabled and (method == (_S[86]) or method == (_S[87])) and tostring(self) == (_S[88]) then
            local m = GetMurderer()
            if m and m.Character and m.Character:FindFirstChild((_S[80])) then
                args[1] = m.Character.HumanoidRootPart.Position
                return oldNamecall(self, unpack(args))
            end
        end
        return oldNamecall(self, ...)
    end)
end

