        task.spawn(function()
            while flying do
                if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild((_S[80])) and LocalPlayer.Character:FindFirstChildOfClass((_S[85])) then
                    local hrp = LocalPlayer.Character.HumanoidRootPart
                    local hum = LocalPlayer.Character:FindFirstChildOfClass((_S[85]))
                    hum.PlatformStand = true

                    local cam = Workspace.CurrentCamera
                    local moveDir = Vector3.zero

                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then moveDir += cam.CFrame.LookVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then moveDir -= cam.CFrame.LookVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then moveDir -= cam.CFrame.RightVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then moveDir += cam.CFrame.RightVector end
                    if UserInputService:IsKeyDown(Enum.KeyCode.Space) then moveDir += Vector3.new(0, 1, 0) end
                    if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then moveDir -= Vector3.new(0, 1, 0) end

                    if moveDir.Magnitude > 0 then
                        hrp.AssemblyLinearVelocity = moveDir.Unit * flySpeed
                    else
                        hrp.AssemblyLinearVelocity = Vector3.zero
                    end
                end
                task.wait()
            end
            if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild((_S[85])) then
                LocalPlayer.Character:FindFirstChildOfClass((_S[85])).PlatformStand = false
            end
        end)
    else
        if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild((_S[85])) then
